var m="https://app.lovoocrm.com/api/nuvemshop-attribution-signal";var c=new Set,s=null;function h(t){let o=t.cart?.id;if(o!=null){let e=String(o).trim();if(/^\d+$/.test(e)&&e!=="0")return e}let n=t.location?.url?.match(/\/checkout\/v3\/[^/]+\/(\d+)\//);return n?n[1]:null}async function l(t){try{let o=await fetch(m,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(t)});if(!o.ok)return console.warn("[lovocrm] attribution response n\xE3o-ok",{status:o.status}),{success:!1,reason:"HTTP_ERROR"};let n=await o.json();return{success:!!n.success,reason:n.reason}}catch{return{success:!1,reason:"FETCH_ERROR"}}}async function _(t){let o=`${t.store_id}:${t.checkout_id}`;if(c.has(o))return;let n=await l(t);if(n.success){c.add(o),console.log("[lovocrm] attribution signal ok",{checkout_id:t.checkout_id});return}if(n.reason==="VISITOR_LINK_NOT_FOUND"){console.log("[lovocrm] attribution retry agendado",{checkout_id:t.checkout_id}),setTimeout(async()=>{if(c.has(o))return;let e=await l(t);e.success?(c.add(o),console.log("[lovocrm] attribution retry ok",{checkout_id:t.checkout_id})):console.log("[lovocrm] attribution retry falhou",{reason:e.reason,checkout_id:t.checkout_id})},3e3);return}console.log("[lovocrm] attribution signal falhou",{reason:n.reason})}function g(t){t.on("customer:update",o=>{let n=o.store?.id,e=h(o),r=o.customer?.contact,i=r?.email?.trim()||null,u=r?.phone?.trim()||null,a=r?.name?.trim()||null;if(!n||!e||!i&&!u)return;s!==null&&(clearTimeout(s),s=null);let d={store_id:n,checkout_id:e,email:i,phone:u,name:a};s=setTimeout(()=>{s=null,_(d).catch(()=>{})},1500)}),t.on("location:updated",()=>{s!==null&&(clearTimeout(s),s=null)})}export{g as App};
